<script setup>
import { onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { apiRequest } from '../services/api.js'
import { selectLocalPath } from '../services/localPicker.js'
const props = defineProps({ conversationId: String, openConversation: Function })
const stopBusy = ref(false)
const state = ref(null), busy = ref(false), error = ref(''), notice = ref('')
const config = reactive({ backend_root: '', desktop_root: '', allow_auto_apply: false })
const configRevision = ref(0)
const goal = ref(''), acceptance = ref(''), selected = ref(null)
let disposed = false, timer
const statuses = { awaiting_idle:'等待任务结束后安装', recovered:'已恢复', recovery_failed:'恢复失败', created:'等待开发', developing:'开发中', validated:'已验证', building:'构建中', built:'候选已构建', previewing:'预览中', preview_ready:'预览就绪', applying:'正在应用', applied:'已应用', completed:'已完成', installing:'正在安装', validating:'检查中', interrupted:'已中断', failed:'失败', stopped:'已停止', cancelled:'已停止', ready:'等待开发' }
async function request(path, method='GET', body) { return apiRequest(`/api/self-upgrade/${path}`, { method, ...(body === undefined ? {} : { body: JSON.stringify(body) }), timeoutMs: method === 'GET' ? 15000 : 600000 }) }
async function load(syncConfig=false) { const value = await request('status'); if (disposed) return; state.value = value; if (syncConfig) { Object.assign(config, value.configuration); configRevision.value = value.configuration.revision } if (selected.value) selected.value = value.jobs?.find(job => job.id === selected.value.id) || selected.value }
async function act(fn) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (cause) { error.value = cause.message } finally { busy.value = false } }
async function choose(key) { await act(async () => { const result = await selectLocalPath('directory'); if (result) config[key] = result.path }) }
async function save() { await act(async () => { await request('configuration','PUT',{ backend_root:config.backend_root, desktop_root:config.desktop_root, allow_auto_apply:config.allow_auto_apply, expected_revision:configRevision.value }); await load(true); notice.value='源码设置已保存。' }) }
async function create() { await act(async () => { const criteria=acceptance.value.split('\n').map(s=>s.trim()).filter(Boolean); if (!criteria.length) throw new Error('请填写至少一条可核对的验收要求。'); selected.value = await request('jobs','POST',{ goal:goal.value, acceptance:criteria, conversation_id:props.conversationId || '', expected_revision:state.value.configuration.revision }); goal.value=''; acceptance.value=''; await load(); notice.value='开发副本已建立，打开开发对话后继续完成改造。' }) }
async function openConversation(job) { await act(async () => { if (!job.conversation_id || !props.openConversation) throw new Error('此任务尚未关联开发对话，请重新读取任务。'); await props.openConversation(job.conversation_id) }) }
async function action(job,name) { await act(async () => { const value = await request(`jobs/${encodeURIComponent(job.id)}/${name}`,'POST',name === 'apply' ? {confirmed:true} : {}); selected.value = value.job || value; await load(); if (name==='apply') notice.value='应用请求已交给独立更新器，请查看实际安装状态。' }) }
async function stop(job) { if (stopBusy.value) return; stopBusy.value = true; try { await request(`jobs/${encodeURIComponent(job.id)}/stop`,'POST',{}); await load(); notice.value='停止请求已送达，任务状态以实际进程结果为准。' } catch (cause) { error.value=cause.message } finally { stopBusy.value=false } }
async function rollback() { await act(async () => { await request('rollback','POST',{confirmed:true}); await load(); notice.value='已建立上一版候选，请查看预览后应用。' }) }
function openPreview(job) { if (!job.preview?.url) return; const url = new URL(job.preview.url, location.href); if (!['http:','https:'].includes(url.protocol) || !['localhost','127.0.0.1','[::1]'].includes(url.hostname)) { error.value='候选预览地址不是本机地址。'; return } window.open(url.href,'_blank','noopener,noreferrer') }
onMounted(() => { void act(()=>load(true)); timer=setInterval(()=>{ if (!busy.value && !document.hidden) void load().catch(()=>{}) },8000) }); onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
</script>
<template>
  <section class="self-upgrade" :aria-busy="busy"><header><div><h1>改造 Mio</h1><p>从源码开发副本到验证、候选预览与本地安装。</p></div><button :disabled="busy" @click="act(()=>load(true))">刷新</button></header><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
    <button v-if="state" :disabled="busy || !state.rollback_available" @click="rollback">恢复上一安装版本</button>
    <p v-if="state?.installed_build" class="installed">当前版本：{{ state.installed_build.version || state.installed_build.build_id || state.installed_build }}</p>
    <form @submit.prevent="create"><label>想增加或修复什么<textarea v-model="goal" rows="2" required :disabled="busy || !state" placeholder="也可以在对话里说：给自己增加一个功能…" /></label><label>验收要求<textarea v-model="acceptance" rows="2" required :disabled="busy" placeholder="至少一条，每行一个能核对的预期结果" /></label><button :disabled="busy || !state || !goal.trim() || !acceptance.trim()">建立改造任务</button></form>
    <article v-for="job in state?.jobs || []" :key="job.id" class="upgrade-card"><header><h2>{{ job.goal }}</h2><small>{{ statuses[job.status] || job.status }}</small></header><p v-if="job.error" class="error">{{ job.error }}</p><p v-if="job.candidate">候选版本：{{ job.candidate.build_id }}</p><p v-if="job.checks?.length">验证：{{ job.checks.map(check => `${check.name}（${check.ok === true || check.passed === true ? '通过' : '未通过'}）`).join('、') }}</p><p v-if="job.needs_confirmation">准备好后，点击应用并重启。</p><div class="actions"><button v-if="job.conversation_id && props.openConversation" :disabled="busy" @click="openConversation(job)">打开开发对话</button><button :disabled="busy" @click="action(job,'validate')">检查改动</button><button :disabled="busy" @click="action(job,'build')">构建候选</button><button :disabled="busy || !job.candidate" @click="action(job,'preview')">启动预览</button><button v-if="job.preview?.url" @click="openPreview(job)">打开预览</button><button :disabled="busy || state?.installer_available === false || !job.candidate || !job.preview?.verified" @click="action(job,'apply')">应用并重启</button><button :disabled="stopBusy || ['completed','failed','cancelled','interrupted','installing'].includes(job.status)" @click="stop(job)">{{ stopBusy ? '正在停止…' : '停止' }}</button></div><details><summary>改动与验证详情</summary><p>开发目录：{{ job.work_root }}</p><p>基线：{{ job.base_build_id }}</p><ul><li v-for="(item,index) in job.acceptance || []" :key="index">{{ item }}</li></ul><pre>{{ JSON.stringify(job.checks || [],null,2) }}</pre><details><summary>完整技术记录</summary><pre>{{ JSON.stringify(job,null,2) }}</pre></details></details></article>
    <p v-if="state && !state.jobs?.length">还没有自身改造任务。</p>
    <details class="source-settings"><summary>源码与安装设置</summary><p v-if="state?.rollback_reason">上一版恢复：{{ state.rollback_reason }}</p><form @submit.prevent="save"><label v-for="(label,key) in {backend_root:'后端源码目录',desktop_root:'桌面应用源码目录'}" :key="key">{{ label }}<div class="path"><input v-model="config[key]" :disabled="busy" /><button type="button" :disabled="busy" @click="choose(key)">选择目录</button></div></label><label class="check"><input v-model="config.allow_auto_apply" type="checkbox" :disabled="busy" />预先授权验证通过后自动本地安装</label><p v-if="state?.execution_environment">{{ state.execution_environment }}</p><p>候选使用隔离配置和合成数据。正式安装由独立更新器处理，失败时按恢复记录回退。</p><button :disabled="busy || !state">保存设置</button></form></details>
  </section>
</template>
<style scoped>
.self-upgrade{display:grid;gap:20px;min-width:0}header,.actions,.path{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.actions{justify-content:flex-start}h1,h2,p{margin:0 0 8px}h2{font-size:calc(15px * var(--fs, 1));font-weight:550;line-height:1.6}p,small{font-size:calc(13px * var(--fs, 1));line-height:1.7;color:var(--text-muted);overflow-wrap:anywhere}form,label{display:grid;gap:10px}button,input,textarea{font:inherit;color:inherit;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:9px 12px}button{cursor:pointer;width:fit-content}button:disabled{opacity:.5;cursor:default}textarea{width:100%;box-sizing:border-box;resize:vertical}.path input{flex:1;min-width:120px}.check{display:flex;align-items:center}.upgrade-card{border-top:1px solid var(--border);padding:20px 0;display:grid;gap:10px}summary{cursor:pointer;font-size:calc(13px * var(--fs, 1));color:var(--text-muted)}details form{margin-top:18px}pre{max-height:280px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:calc(12px * var(--fs, 1))}.error{color:var(--danger)}.source-settings{border-top:1px solid var(--border);padding-top:20px}
</style>
